export const GAME_URL='https://lotus-moba-lab-jarvais.snowypanda18.chatgpt.site/';
export function creatorRoadmap(state){return `<section class="creator-path" aria-label="AI产品创作路线"><div class="creator-path-head"><div><span class="eyebrow">BUILD → SHOW → LEARN</span><h2>AI 产品实践路线</h2></div><a href="./creator-plan.html" target="_blank" rel="noopener">计划表与运营小教学 ↗</a></div><div class="creator-stops">${[[1,'个人网站','01–06课'],[7,'五位荣耀','07–09课'],[10,'游戏 / 趣味测试','10–15课'],[16,'宣传视频','16–18课'],[19,'小红书运营','19–21课'],[22,'个人作品集','22–24课']].map(([id,name,range])=>`<a href="#lesson-${id}"><small>${range}</small><strong>${name}</strong></a>`).join('')}</div><p>只选一个主推产品，按自己的节奏推进。今天很忙？先做当前课的第一步，10分钟也算开始。</p>${state.routeArchive?'<p class="route-migration-note">路线已更新：01–06课的原进度保留；07–24课改为创作实践，旧勾选与草稿已归档，原学习感想仍可查看。旧完成标记不会冒充新版任务已完成。</p>':''}</section>`;}
export function creatorLessonExtras(id){
 if(id>=7&&id<=9)return `<section class="creator-tip"><strong>接着现有游戏做</strong><p>这里的「五位荣耀」沿用你的现有游戏。已有功能直接试玩验证，遇到实际问题再改。</p><a href="${GAME_URL}" target="_blank" rel="noopener">打开现有游戏 ↗</a></section>`;
 if(id>=10&&id<=15)return '<section class="creator-tip"><strong>首发只做一个</strong><p>继续游戏，或者做「历史人物风格 / 游戏队友类型 / 宿舍角色」原创测试，二选一。测试仅供娱乐；0.1元是待验证的试价想法，能否上架、如何交付，以自己账号的后台和现行规则为准。</p></section>';
 if(id>=16&&id<=18)return '<section class="creator-tip"><strong>20–30秒文稿骨架</strong><p>0–3秒：展示一个好玩的结果。3–8秒：一句话说谁能玩。8–20秒：真实录屏，演示关键操作。20–30秒：结果＋当前允许的站内体验入口。由Codex先写，你确认事实和语气，再录屏剪片。</p><a href="./creator-plan.html#video" target="_blank" rel="noopener">看示例文稿与录屏清单 ↗</a></section>';
 if(id>=19&&id<=21)return '<section class="creator-tip"><strong>运营从这三类内容开始</strong><p>真实试玩：让人看懂好玩在哪。制作过程：展示你怎样用AI改出功能。反馈迭代：说明玩家卡在哪里、你修了什么。先自然发布与自愿试用，每天10分钟记数据；不默认付费投流。</p><a href="./creator-plan.html#operations" target="_blank" rel="noopener">看7天任务表、数据表与规则来源 ↗</a></section>';
 return '';
}
export function archivedAI(state,esc){const a=state.routeArchive;if(!a)return '';return `<details class="lesson-panel ai-route-archive"><summary>查看旧AI路线的进度与草稿（历史归档）</summary><p>旧路线完成 ${a.completed.length} 课；完整归档随「数据与备份」一起导出。旧笔记保留原课名，仍在上方学习感想里。</p><p>原已完成课号：${a.completed.length?a.completed.join('、'):'无'}</p>${Object.entries(a.steps).filter(([id])=>Number(id)>=7).map(([id,steps])=>`<p>旧第${esc(id)}课：保留 ${steps.length} 项步骤勾选。</p>`).join('')}${Object.entries(a.drafts).filter(([id])=>Number(id)>=7).map(([id,text])=>`<h3>旧第${esc(id)}课草稿</h3><p class="archived-draft">${esc(text)}</p>`).join('')}</details>`;}
export function creatorResources(){return `<span class="eyebrow">JARVAIS WANG · CREATOR PRACTICE</span><h2 id="dialog-title">AI创作与产品实践</h2><p>网站里的24课已更新为：网页 → 游戏或趣味测试 → 宣传视频 → 小红书运营 → 作品集。每课都有操作、示例指令和完成标准。</p><a class="resource-link" href="./creator-plan.html" target="_blank" rel="noopener"><span><strong>新版计划表与运营小教学 ↗</strong><small>24课清单、20–30秒文稿、7天行动表、规则来源；可打印保存PDF。</small></span></a><a class="resource-link" href="${GAME_URL}" target="_blank" rel="noopener"><span>现有「五位荣耀」游戏 ↗</span></a><p class="backup-warning">0.1元仅为待核实的试价设想，不承诺可上架或盈利。旧路线资料留作历史备份，已不作为今日任务。</p>`;}
